INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (4, '인모드', '리프팅', '양극성 고주파(RF)와 석션으로 지방 감소와 피부 탄력을 동시에 개선하는 비침습 장비', '얼굴 지방 감소, 탄력, 턱선 정리', '양극 RF + 석션으로 지방 세포 파괴 및 콜라겐 수축. 에피더럴 모니터링으로 피부 온도 초당 1000회 측정, 자동 온도 조절', 'Forma(진피 타이트닝), MiniFX(얼굴 지방), BodyFX(바디), TONE(근육 강화) 등 다양한 팁. FDA 승인', '["인모드 (바디팁 있음)"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (5, '텐써마', '리프팅', '6.78MHz 단극성 고주파(RF)로 진피층에 열에너지를 전달하는 리프팅 장비. 최대 400W, 유효출력 237W', '피부 탄력, 처짐, 주름', '6.78MHz 단극 RF로 진피층 콜라겐 수축 및 신생 유도', '텐텍 자체 개발. 써마지 계열과 유사 원리', '["텐트리플"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (6, '네오빔', '여드름/피지', '1450nm 다이오드 레이저로 피지선에 선택적으로 작용하여 여드름을 개선하는 장비', '여드름, 피지 과다, 모공', '1450nm 다이오드 레이저가 수분·유분 흡수도 높아 피지선 선택적 위축 → 피지 분비 감소. DCD(피부냉각장치)로 표피 보호', '통증이 적고 다운타임 짧아 반복 시술에 적합. 다양한 렌즈 사이즈', '[]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'equipment', 4);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (7, '아그네스', '여드름/피지', '미세 절연침을 이용해 피지선에 직접 RF 에너지를 전달, 피지선을 선택적으로 파괴하는 여드름 치료', '여드름, 피지 과다, 한관종', '미세 절연침(Insulated Needle)이 피지선에 정확히 위치 → RF 열에너지로 피지선 선택적 파괴', '여러 RF 장비(포텐자, 시크릿, 버츄 등)에서 아그네스 모드 지원. 한관종 치료에도 사용', '["시크릿 아그네스", "포텐자 아그네스", "버츄 아그네스", "한관종 아그네스"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'equipment', 4);
