INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (15, '포텐자', 'RF 마이크로니들', 'RF 마이크로니들 장비. 니들을 통해 진피층에 직접 고주파 에너지를 전달하여 피부 재생·리프팅', '모공, 흉터, 주름, 탄력, 여드름', '마이크로니들이 진피층에 삽입 → RF 에너지 직접 전달 → 콜라겐 리모델링', '국내 최초 RF 마이크로니들 의료기기. 사이노슈어와 ODM 계약으로 글로벌 유통. 다이아 리프팅, 아그네스(여드름) 모드', '["포텐자 다이아리프팅", "포텐자 다이아몬드리프팅", "포텐자 아그네스"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'care', 5);
