INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (17, '소노', '관리기기(초음파)', '초음파를 이용한 피부 관리 장비. 영양 성분 침투 촉진 및 진정 효과', '피부 보습, 영양 공급, 진정', '초음파 진동으로 세포막 투과성 증가 → 영양 성분 흡수 촉진', '소노케어, 소노 LDM 등 다양한 모델. 관리 시술 기본 장비', '["소노케어"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (18, '크라이오', '관리기기', '냉각(Cryotherapy) 기술을 이용한 피부 관리 장비. 진정·모공 축소·부기 감소', '피부 진정, 모공 축소, 부기 감소', '저온 냉각으로 혈관 수축 → 진정 + 모공 타이트닝', '단독 또는 다른 시술(비타민, 이온자임 등)과 병행하는 관리 보조 장비', '["크라이오셀"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (19, 'LDM', '관리기기(초음파)', '저주파~고주파 초음파를 활용한 피부 관리 장비. 보습·진정·재생 효과', '피부 보습, 진정, 재생, 여드름 진정', '듀얼 주파수 초음파(3MHz+10MHz)가 세포막 투과성 증가 → 영양 성분 흡수 촉진 + 항염 효과', 'LDM MED, LDM 스마트 트라이 등 다양한 모델. 관리 시술용 보조 장비', '["LDM MED", "LDM med tri", "LDM smat tri", "LDM 스마트", "ldm med", "소노 LDM", "스마트 LDM"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (20, '이온자임', '관리기기', '이온토포레시스+효소(자임) 결합 관리 장비. 미세 전류로 영양 성분 침투를 촉진', '피부 보습, 영양 공급, 진정', '미세 전류(이온토포레시스)로 수용성 영양 성분의 경피 흡수 촉진', '이온토, 이온터치 등 유사 장비. 소노(초음파), 스크러버(각질제거)와 함께 관리 3종 기본 구성', '["이온토", "이온터치", "이온토 3종"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'care', 7);
