INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (26, '바디인모드', '바디', '인모드의 바디 전용 구성. 고주파(RF)로 체지방 감소와 피부 탄력을 동시에 개선', '복부, 팔뚝, 허벅지 등 체지방 + 피부 처짐', '양극 RF + EMS로 지방 감소 및 근육 자극', 'BodyFX(바디 지방), TONE(근육 강화) 팁 사용', '["바디 인모드", "인모드 (바디", "인모드(바디", "바디인모드FX"]', 0, 0, '2026-04-03 14:27:26', '2026-04-06 08:59:31', 'equipment', 6);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (27, '울쎄라피 프라임', '리프팅', '고밀도 집속 초음파(HIFU)로 SMAS층까지 에너지를 전달하여 콜라겐 재생을 촉진하는 비침습 리프팅 장비', '얼굴 처짐, 턱선, 이중턱, 눈썹 리프팅', 'HIFU(High Intensity Focused Ultrasound)로 진피~SMAS층(최대 8mm)에 열응고점 생성 → 콜라겐 리모델링. DeepSEE 기술로 실시간 초음파 영상 확인', 'FDA 승인 리프팅 장비. 프라임은 기존 울쎄라 대비 시술 속도 20% 향상, 통증 경감. 품목명: 집속형초음파자극시스템', '["울쎄라피프라임","울쎄라피 프라임/","아이울쎄라피프라임"]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 10:41:03', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (28, '써마지FLX', '리프팅', '단극성 고주파(RF)로 진피층 콜라겐을 수축·신생시켜 피부 탄력을 개선하는 비침습 리프팅 장비', '피부 탄력 저하, 잔주름, 모공, 눈가', '6.78MHz 단극 RF로 진피층에 열에너지 전달 → 콜라겐 수축 및 신생 유도. AccuRep 기술로 정밀 에너지 조절, Comfort Pulse Technology로 통증 완화', '4세대 모델. Total Tip 4.0(얼굴), Eye Tip 0.25(눈가), Body Tip 16.0(바디). 최대 출력 400W. 시술 시간 기존 대비 25% 단축', '["써마지 FLX", "써마지flx", "써마지 flx", "4세대 써마지flx", "미니 써마지"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (29, '써마지', '리프팅', '단극성 고주파(RF)로 피부 콜라겐을 수축시켜 탄력을 높이는 리프팅 장비', '피부 탄력 저하, 잔주름', '단극 RF로 진피층 콜라겐 수축 및 신생 유도', '써마지 시리즈의 이전 세대 모델. FLX가 최신 4세대', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (30, '슈링크 유니버스', '리프팅', '고밀도 집속 초음파(HIFU)로 진피~SMAS층에 열응고점을 생성하여 피부 탄력과 리프팅 효과를 주는 비침습 장비', '얼굴 처짐, 턱선, 탄력, 눈가·입가·목 주름', 'HIFU로 피부 깊이별 열응고점 생성 → 콜라겐 리모델링. 다양한 카트리지(2mm~)로 부위별 맞춤 시술', '국내 HIFU 시장 점유율 55% 1위. 누적 판매 15,000대 이상. 식약처 2mm 카트리지 눈가·입가·목 주름 사용 목적 확대 승인. 바디 카트리지도 출시', '["슈링크유니버스", "유니버스슈링크", "유니버스 슈링크"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (31, '올리지오X', '리프팅', '고주파(RF) 에너지를 활용한 프리미엄 리프팅 장비. 조직에 열을 전달하여 콜라겐 리모델링 유도', '피부 탄력, 처짐, 모공', '단극성 고주파(RF)로 진피층에 열에너지 전달 → 콜라겐 리모델링. G/X 듀얼모드로 환자 맞춤 에너지 출력 선택', '기존 올리지오 대비 에너지 전달·쿨링 시스템 강화. 대만, 브라질, 태국 등 글로벌 인증 획득', '["올리지오 X", "올리지오x", "올리지오", "올리지오 KISS", "올리지오 키스"]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 13:03:07', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (32, '볼뉴머', '리프팅', '6.78MHz 단극성 고주파(모노폴라 RF)로 진피층 깊숙이 열에너지를 전달하여 콜라겐 리모델링을 유도하는 리프팅 장비', '피부 탄력, 처짐, 모공, 볼 꺼짐', '6.78MHz 모노폴라 RF 에너지를 진피층에 전달 → 열에너지 변환 → 콜라겐 리모델링. 히든엣지 디자인으로 방사형 에너지 전달', 'FDA·식약처 허가. 6단계 쿨링, 5단계 진동, 360도 틸팅 팁. 4가지 크기의 시술 팁', '["볼링크"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (33, '온다리프팅', '리프팅/바디', '마이크로파(Coolwaves) 기술로 피부 탄력 개선과 지방 분해를 동시에 수행하는 비침습 장비', '이중턱, 턱선, 얼굴 지방, 바디 지방', '극초단파(Microwave, Coolwaves™)로 피하 지방층을 선택적으로 파괴 → 지방 감소 + 피부 수축. RF/HIFU와 다른 마이크로파 원리', '특허받은 Coolwaves™ 기술. 시술 시간 10~20분, 다운타임 없음. 페이스/바디 팁 구분', '["온다 리프팅", "온다", "온다 바디", "온다 페이스", "바디온다", "바디온다리프팅"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (34, '클라리티2', '레이저(색소/혈관/제모)', '알렉산드라이트(755nm)와 Nd:YAG(1064nm) 이중 파장 레이저로 색소·혈관·제모 등 다목적 치료가 가능한 복합 레이저', '기미, 주근깨, 홍조, 혈관, 제모, 모공, 흉터', '755nm(알렉산드라이트) + 1064nm(Nd:YAG) 이중 파장. IntelliTrak 기술로 균일한 에너지 전달, 실시간 온도 측정 자동 차단', '클라리티 프로의 후속 모델. FDA, CE, KFDA 인증. 인텔리전트 케어 시스템 탑재', '["클라리티 2", "Clarity II"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (35, '클라리티 프로', '레이저(색소/혈관/제모)', '알렉산드라이트(755nm)와 Nd:YAG(1064nm) 이중 파장 레이저. 클라리티2의 전 모델', '색소, 혈관, 제모', '755nm + 1064nm 이중 파장', '클라리티2가 후속 모델', '["클라리티 롱펄","클라리티롱펄"]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 10:41:03', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (36, '보톡스', '주사 시술', '보툴리눔 톡신을 주입하여 근육 움직임을 줄여 주름을 펴고 윤곽을 다듬는 시술', '이마 주름, 눈가 주름, 사각턱, 승모근', '보툴리눔 톡신이 신경-근육 접합부의 아세틸콜린 분비 억제 → 근육 이완', '보톡스(앨러간), 디스포트(입센), 제오민(머츠), 나보타(대웅), 코어톡스(메디톡스), 리즈톡스(휴젤) 등 다양한 제품', '["스킨보톡스", "다한증 보톡스", "다한증보톡스"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (37, '디스포트', '주사 시술', '보툴리눔 톡신 A형 제제. 보톡스와 동일 기전으로 근육 이완 효과', '이마 주름, 눈가 주름, 사각턱', '보툴리눔 톡신 A형이 신경-근육 접합부의 아세틸콜린 분비 억제', '입센사 제품. 보톡스 대비 확산 범위가 넓어 넓은 부위 시술에 유리', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (38, '리쥬란', '스킨부스터', '연어 DNA 유래 폴리뉴클레오타이드(PN)를 피부에 주입해 자가 재생력을 높이는 스킨부스터', '피부 탄력, 잔주름, 모공, 다크서클', 'PN(Polynucleotide)이 섬유아세포 활성화 → 콜라겐·엘라스틴 자체 생성 촉진', '식약처 허가(품목허가 제허 14-825호). 리쥬란 힐러(기본), HB(보습강화, PN+HA), HB Plus(개선형), I(눈가전용), S(스칼프) 라인업', '["리쥬란 힐러", "리쥬란힐러", "리쥬란 HB", "리쥬란HB", "리쥬란HB+", "리쥬란 HB Plus", "리쥬란 I", "리쥬란 S", "리쥬란아이", "리쥬란 아이", "리쥬란힐러", "리쥬란 스킨부스터 앰플", "리쥬란힐러, HB, 아이"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (39, '쥬베룩', '스킨부스터', 'PDLLA(폴리-D,L-락틱산) 미립자와 히알루론산(HA)이 결합한 콜라겐 생성 스킨부스터', '피부 탄력, 잔주름, 볼 꺼짐', 'PDLLA 미립자가 진피층에서 콜라겐 신생 유도 + HA로 즉각 보습', '쥬베룩 스킨(전체 피부결), 쥬베룩 볼륨(볼꺼짐·리프팅). PDLLA는 옥수수·사탕수수 전분 유래, FDA 인체 사용 승인 소재', '["쥬베룩 스킨", "쥬베룩스킨", "쥬베룩 볼륨", "쥬베룩볼륨", "쥬베룩스킨,쥬베룩볼륨"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (40, '필러', '주사 시술', '히알루론산(HA) 등을 주입해 꺼진 부위를 채우고 윤곽을 다듬는 시술', '팔자주름, 볼 꺼짐, 턱 끝, 코, 입술', '히알루론산 겔이 피부 볼륨을 즉시 채움 + 수분 유지', '쥬비덤(앨러간), 레스틸렌(갈더마), 벨로테로(머츠), 뉴라미스(메디톡스) 등. 부위별 점도 다르게 사용', '["필러 없음", "필러 쥬비점"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (41, '쥬비덤', '주사 시술(필러)', '히알루론산(HA) 기반 필러 브랜드. VYCROSS 기술로 자연스러운 볼륨감과 긴 유지 기간', '팔자주름, 볼 꺼짐, 입술, 턱', '히알루론산 겔 주입으로 볼륨 충전', '글로벌 필러 시장 점유율 38%. 볼룩스(볼륨), 볼벨라(입술), 볼리프트(중안면) 등 라인업', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (42, '벨로테로', '주사 시술(필러)', '히알루론산(HA) 필러 브랜드. CPM 기술로 조직 통합성이 뛰어남', '잔주름, 입술, 눈밑', '히알루론산 겔 주입', '벨로테로 소프트, 밸런스, 인텐스, 볼륨 라인업. 리바이브(스킨부스터 용도)', '["벨로테로 리바이브", "벨로테로 소프트"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (43, '레스틸렌', '주사 시술(필러)', '히알루론산(HA) 필러 브랜드. NASHA/OBT 기술 기반', '주름, 볼 꺼짐, 입술', '히알루론산 겔 주입', '레스틸렌 키스(입술), 리프트(중안면) 등 라인업', '["레스틸렌 키스"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (44, '스킨바이브', '스킨부스터', '쥬비덤 라인의 스킨부스터. 히알루론산(HA)을 진피에 주입하여 피부 보습·탄력 개선', '피부 보습, 탄력, 피부결 개선', '저점도 히알루론산이 진피에 분포하여 수분 유지 + 탄력 개선. 필러와 달리 볼륨 충전 목적이 아님', '쥬비덤 스킨바이브. 필러와 동일 HA 성분이나 점도·교차결합 정도가 다름', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (45, '피코슈어', '레이저(색소)', '755nm 알렉산드라이트 피코세컨드 레이저. 세계 최초 피코초 레이저', '기미, 색소, 문신 제거, 모공, 흉터', '피코세컨드(10⁻¹² 초) 펄스로 색소 입자를 미세하게 파쇄 → 체내 흡수 제거. 755nm 파장은 멜라닌 흡수율 높음', 'Focus Lens Array로 프락셀 모드 가능. FDA 승인 기미 개선 레이저', '["피코슈어 토닝", "피코슈어 포커스", "피코슈어 프락셀", "피코슈어MLA", "피코슈어프로", "피코 슈어", "피코알렉스"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (46, '피코플러스', '레이저(색소)', '4가지 파장의 피코세컨드/나노세컨드 듀얼 펄스 레이저. 색소·문신·모공·흉터 다목적 치료', '기미, 색소, 문신 제거, 모공, 흉터', '피코(ps) + 나노(ns) 2가지 펄스모드, 1064/532/595/660nm 4파장, Focused Dots 핸드피스 포함 총 6종', '식약처 기미 개선 허가 피코레이저. MLA(Micro Lens Array) 프락셀 가능', '["피코플러스 MLA","피코플러스 토닝","피코플러스 피코프락셀","피코 플러스"]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 10:41:03', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (47, '피코토닝', '레이저(색소)', '피코세컨드 레이저를 저출력으로 반복 조사하여 색소를 점진적으로 개선하는 토닝 시술', '기미, 잡티, 피부 톤 불균일', '피코초 레이저 저출력 반복 조사 → 멜라닌 점진적 파괴', '장비가 아닌 시술 모드. 피코슈어, 피코플러스, 피코웨이 등 다양한 피코레이저로 수행', '["피코 토닝"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (48, '헐리우드 스펙트라', '레이저(색소/토닝)', 'Nd:YAG 레이저 기반 토닝 특화 장비. 색소·모공·흉터 복합 치료', '기미, 색소, 모공, 흉터, 피부결', '1064nm Nd:YAG 레이저의 Q-switched + Q4 모드 → 레이저 토닝. IntelliBeam 기술로 균일 에너지 전달', 'Q4 모드가 기존 PTP 모드보다 토닝 효과 탁월. 콜라겐 재생, 홍조, 피부결 개선', '["헐리우드스펙트라", "헐리우드 토닝", "헐리우드 프락셀", "헐리우드 MLA", "스펙트라"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (49, '더마브이', '레이저(색소/혈관)', '롱펄스 532nm + Nd:YAG 1064nm 듀얼 파장 레이저. 색소 및 혈관 병변 치료', '기미, 잡티, 홍조, 혈관 병변, 피부 톤', '532nm(KTP) + 1064nm(Nd:YAG) 듀얼 파장. 균일한 에너지 전달로 색소·혈관 동시 치료', '10개국 이상 인허가 완료. FDA 승인. 토닝 시술에도 활용', '["디마브이"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (50, '젠틀맥스 프로 플러스', '레이저(제모/색소/혈관)', '알렉산드라이트(755nm) + Nd:YAG(1064nm) 듀얼 파장 레이저. 제모·색소·혈관 다목적 치료', '제모, 색소, 혈관, 피부 탄력', '755nm(알렉산드라이트) + 1064nm(Nd:YAG) 듀얼 파장. 쿨링 가스로 표피 보호', 'GentleMax Pro의 업그레이드 모델. 출력·치료 효율 향상. 칸델라 Gentle 시리즈', '["젠틀맥스프로플러스", "젠틀맥스 프로플러스", "젠틀맥스프로", "젠틀맥스 프로"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 8);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (51, '실펌X', 'RF 마이크로니들', '듀얼 웨이브 방식의 비절연성 마이크로니들 RF 장비. 색소·타이트닝·리프팅 다목적 시술', '기미, 홍조, 모공, 흉터, 탄력', '비절연성 마이크로니들을 통해 RF 에너지를 진피 전 층에 전달. 연속파(CW) + 펄스파(PW) 듀얼 웨이브', '비올 원천기술(비절연성 마이크로니들). FDA, CE 인증. 기미 치료 등 다양한 임상', '["실펌", "실펌 X"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (52, '시크릿RF', 'RF 마이크로니들', '마이크로니들을 이용한 고주파(RF) 의료기기. 피부 깊이별 맞춤 RF 에너지 전달', '모공, 흉터, 주름, 탄력, 여드름', '마이크로니들 전극으로 최소침습 RF 에너지 전달. 니들 깊이 조절 가능', '2017년 미국 FDA 인증. 국내 약 600여 개 병원 도입. 일본 PMDA 허가 획득. 시크릿 프로 추가 FDA 승인', '["시크릿", "시크릿 RF", "시크릿니들RF", "시크릿 아그네스"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 5);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (53, '버츄RF', 'RF 마이크로니들', '마이크로니들 고주파(RF) 레이저 의료기기. ACS 쿨링 시스템과 40단계 깊이 조절', '모공, 흉터, 주름, 탄력', '마이크로니들(0.1~4.0mm, 40단계)로 진피층에 RF 에너지 전달. ACS 첨단 쿨링 시스템으로 표피 보호', 'FDA, CE, MFDS 인증. 기미모드, 리프팅모드, 모공모드, 아그네스(여드름)모드 등 다양한 시술 프로그램', '["버츄", "버츄 RF", "버츄RF", "버츄리프팅", "버츄아그네스", "버츄모공모드", "버츄프락셀", "버츄 기미모드", "버츄 리프팅", "버츄 모공", "버츄 아그네스", "버츄 여드름모드", "버츄 윤곽리프팅"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 5);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (54, '덴서티', '리프팅', '6.78MHz 모노폴라/바이폴라 듀얼 고주파(RF) 리프팅 장비. 최대 400W 출력으로 깊은 피부층까지 에너지 전달', '피부 탄력, 처짐, 주름, 모공', '6.78MHz 모노폴라(단극성) + 바이폴라(양극성) RF. 진피층~근막층까지 최대 400W 에너지 조사. 임피던스 체크 + 피부 온도 측정, 5단계 쿨링', 'FDA 510K 승인. 미주 지역 ''DENZA'' 명칭으로 출시. 덴서티 알파, 하이, 클래식 라인업', '["덴서티 알파", "덴서티 하이", "덴서티클래식"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (55, '플래티넘PTT', '여드름/피지', '백금(Platinum) 나노입자를 피부에 침투시킨 후 레이저를 조사하여 열로 전환, 피지선과 여드름균을 파괴하는 광열치료', '염증성 여드름, 피지 과다, 모공', 'PTT(Photothermal Therapy): 140nm 백금 나노입자가 모근까지 침투 → 레이저 조사 → 열 전환 → 피지선·여드름균 파괴', 'PDT(광역동치료)→골드PTT→플래티넘PTT 순으로 발전. 장비가 아닌 시술 프로토콜', '["골드PTT", "골드 PTT", "에토좀PTT", "에토좀 PTT", "PTT", "ptt", "PDT"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 4);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (56, '리투오', '스킨부스터', 'hADM(무세포동종진피) 기반 ECM(세포외기질) 스킨부스터. 피부 기저부터 재생을 돕는 차세대 스킨부스터', '피부 탄력, 잔주름, 피부결, 재생', 'hADM 성분이 ECM(세포외기질)을 직접 보충 → 피부 기저층부터 재생 촉진', '기존 PN(리쥬란) 스킨부스터와 다른 ECM 부스터 카테고리. 엘라비에 리투오가 정식 명칭. 리프팅 아님, 스킨부스터임', '["엘라비에 리투오"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (57, '엑소좀', '스킨부스터', '줄기세포 유래 엑소좀을 동결건조하여 피부에 적용하는 4세대 스킨부스터', '피부 재생, 탄력, 피부결, 손상 회복', 'ExoSCRT™ 기술로 생산된 줄기세포 엑소좀이 섬유아세포 활성화 → 피부 자가 재생 촉진', 'ASCE+가 브랜드명. 2019년 출시. 동결건조 형태로 안정성 확보', '["ASCE 엑소좀", "엑소좀 asce", "엑소좀asce", "ASCE+ 엑소좀", "엑소힐러"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (58, '물광주사', '스킨부스터', '히알루론산(HA) 등 보습·영양 성분을 진피층에 미세 주입하여 피부 보습·탄력 개선하는 시술 총칭', '피부 보습, 탄력, 피부결, 광채', '자동 주입 기기(더마샤인, 메소건 등)로 HA 등을 진피층에 균일 주입', '특정 장비명이 아닌 시술 카테고리. 리쥬란, 쥬베룩 등과 별도의 HA 물광 시술', '["물톡스", "광채주사"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (59, '티타늄', '레이저(리프팅/제모)', '755/810/1064nm 3파장 동시 조사 레이저. 리프팅·타이트닝·제모·브라이트닝 복합 효과', '피부 탄력, 리프팅, 제모, 피부 톤', '755+810+1064nm 3파장 동시 조사(초당 150회). 사파이어 컨택 쿨링으로 표피 보호', '소프라노 티타늄이 정식명. KFDA 승인. 통증 적고 다운타임 없음', '["티타늄 리프팅", "티타늄리프팅", "티타늄제모"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (60, '소프웨이브', '리프팅', 'SUPERB 기술로 진피 1.5mm 깊이에 초음파 열에너지를 수평 전달하는 비침습 리프팅 장비', '눈가, 입가, 목 주름, 얼굴 리프팅', 'SUPERB(Synchronous Ultrasound Parallel Beam): 7개 평행 초음파 빔으로 1.5mm 진피층에 60~70℃ 열에너지 정밀 전달 → 콜라겐·엘라스틴 재생', 'FDA 눈썹 리프팅, 목·얼굴 주름 개선 승인. 얇고 민감한 부위에도 안전', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (61, '올리디아', '콜라겐 촉진제', 'PLLA(폴리-L-락틱산) 기반 콜라겐 촉진 주사제. 자가 콜라겐 생성을 유도하여 볼륨·탄력 개선', '볼 꺼짐, 주름, 피부 탄력', 'PLLA 미세입자가 진피층에서 서서히 분해되며 콜라겐 신생 유도. 4~6주 후 효과 발현', '식약처 4등급 의료기기 허가(조직수복용재료). 유럽 CE 인증(2021). 스컬트라 대비 균일 입자·빠른 현탁', '["올리디아 120", "올리디아 365", "올리디아 마요", "올리디아마요 120"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (62, 'CO2 레이저', '레이저(재생/흉터)', '10,600nm 파장의 이산화탄소(CO2) 레이저. 점 제거, 흉터 치료, 프락셀 시술에 사용', '점 제거, 흉터, 사마귀, 피부 재생', '10,600nm CO2 레이저가 수분에 흡수 → 조직 기화/절제. 프락셔널 모드로 미세 열손상 구역 생성 가능', 'CO2 프락셀, 포스티안, 헤스티아 등 다양한 모델명. 점 제거 시 가장 일반적인 레이저', '["CO2", "co2", "Co2", "CO2레이저", "co2레이저", "co2 레이저", "CO2프락셀", "co2프락셀", "CO2 DS-40U", "헤스티아", "헤스티아 co2", "헤스티아 프락셀", "포스티안"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (63, 'IPL', '레이저(색소/혈관/제모)', '강한 펄스 광선(Intense Pulsed Light)을 사용한 비레이저 광치료기. 색소·혈관·제모 등 복합 치료', '색소, 홍조, 혈관, 제모, 피부 톤', '다파장(500~1200nm) 광에너지를 필터로 선별 조사 → 멜라닌/헤모글로빈 선택적 흡수', 'M22(루미너스), 셀렉V(큐테라) 등 다양한 모델. 레이저와 달리 단일 파장이 아닌 광대역', '["M22 IPL", "셀렉 IPL", "VP540"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (64, '아포지', '레이저(제모/색소/혈관)', '알렉산드라이트(755nm) + Nd:YAG(1064nm) 듀얼 파장 레이저. 제모·색소·혈관 치료', '제모, 색소, 혈관', '755nm + 1064nm 듀얼 파장', '아포지 엘리트 플러스가 주요 모델. 사이노슈어의 대표 제모 레이저', '["아포지 엘리트 플러스", "아포지 플러스", "아포지 플러스 2", "아포지 플러스 엘리트", "아포지엘리트플러스", "아포지플러스"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 8);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (65, '브이빔', '레이저(혈관/홍조)', '595nm 펄스다이 레이저(PDL)로 혈관 병변과 홍조를 치료하는 혈관 레이저', '홍조, 혈관 확장, 여드름 홍반, 흉터', '595nm 파장이 헤모글로빈에 선택적 흡수 → 혈관 응고·파괴', '브이빔 퍼펙타가 최신 모델. 혈관 레이저의 골드 스탠다드', '["브이빔퍼펙타", "브이빔 퍼펙타"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (66, '프락셀', '레이저(재생/흉터)', '프락셔널(분획) 레이저 시술의 총칭. 미세 열손상 구역을 만들어 피부 재생을 유도', '흉터, 모공, 주름, 피부 재생', '레이저를 미세 점으로 분산 조사 → 미세 열손상 구역(MTZ) 생성 → 주변 정상 조직이 재생 촉진', 'CO2 프락셀, 어븀 프락셀, 피코 프락셀 등 다양한 종류. 특정 장비명이 아닌 시술 방식', '["어븀프락셀", "어븀 프락셀", "MLA 프락셀", "헐리우드 프락셀"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 5);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (67, '스컬트라', '콜라겐 촉진제', 'PLLA(폴리-L-락틱산) 기반 콜라겐 촉진 주사제. 자가 콜라겐 생성 유도', '볼 꺼짐, 주름, 피부 탄력', 'PLLA 미세입자가 진피층에서 분해되며 콜라겐 신생 유도', '올리디아와 동일 계열(PLLA). FDA 승인', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (68, '더모톡신', '주사 시술', '보툴리눔 톡신을 미량으로 진피층에 다점 주입하는 스킨 보톡스 시술', '모공, 피지, 피부결, 탄력', '소량의 보톡스를 진피층에 주입 → 피지선 축소 + 모공 타이트닝', '일반 보톡스(근육주사)와 다른 진피 주입 방식', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (69, 'FCR필링', '필링', '산호초(Coral Calcium) 미세입자를 피부에 문질러 각질 제거 및 피부 재생을 유도하는 필링 시술', '모공, 잡티, 피부결, 여드름 흉터', '산호초 미세입자가 물리적으로 각질층 제거 + 진피 자극 → 재생 촉진', '천연 해양 미네랄 성분. 다운타임 2~3일. 화학 필링과 달리 물리적 필링', '["FCR", "FCR 필링", "fcr필링"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (70, '레디어스', '콜라겐 촉진제(필러)', '칼슘하이드록시아파타이트(CaHA) 기반 필러. 즉각 볼륨 + 장기 콜라겐 촉진 이중 효과', '볼 꺼짐, 팔자주름, 턱선', 'CaHA 미세입자가 즉시 볼륨 충전 + 시간이 지나며 분해되면서 콜라겐 신생 유도', '래디에스(Radiesse)가 영문명. HA 필러와 달리 콜라겐 촉진 효과 있음. 스킨부스터 버전도 출시', '["래디어스", "레디어스 (콜라겐 부스터)"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (71, '울트라콜', '스킨부스터', 'PDO(폴리디옥사논) 성분 기반 스킨부스터. 진피층에서 콜라겐 재생 유도', '피부 탄력, 잔주름, 피부결', 'PDO 미세입자가 진피에서 분해되며 콜라겐 신생 유도', '울트라콜 100, 200 등 용량별 라인업', '["울트라콜 100", "울트라콜200"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (72, '실리프팅', '리프팅(실)', 'PDO/PCL/PLLA 등 흡수성 실(Thread)을 피부 아래에 삽입하여 물리적으로 리프팅하는 시술', '얼굴 처짐, 턱선, V라인', '코그(가시)가 달린 흡수성 실을 삽입 → 물리적 당김 + 실 주변 콜라겐 재생', '민트실, 실루엣소프트 등 다양한 제품. 시술 후 1~2주 회복기간', '["실 리프팅", "민트실", "민트실리프팅", "실루엣소프트", "실루엣소프트 실리프팅", "실루엣픽스실", "옥토실", "엠보스몰드실", "모노실"]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 13:03:07', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (73, '아쎄라', '주사/부스터', '[지방분해주사 — 본문 작성 필요] 아쎄라 지방분해주사 (얼굴/바디 모두 사용).', '[지방분해주사 — 본문 작성 필요]', '[지방분해주사 — 본문 작성 필요]', '원텍 제조. 얼굴/바디 팁 구분', '["아쎄라 윤곽","얼굴아쎄라","페이스 아쎄라"]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 10:42:17', 'injection', 6);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (74, '엔디야그', '레이저(색소/혈관/토닝)', '1064nm Nd:YAG 레이저의 총칭. 색소·혈관·토닝 등 다목적 사용', '색소, 혈관, 토닝, 제모', '1064nm 파장이 깊은 진피까지 도달 → 멜라닌/헤모글로빈 흡수', '장비명이 아닌 레이저 파장/종류의 총칭. 헐리우드 스펙트라, 레블라이트 등이 대표적 Nd:YAG 레이저. 리프팅이 아님 — 색소/혈관/토닝 레이저', '["엔디야그 레이저"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', NULL);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (75, '포토나', '레이저(색소/재생)', 'Er:YAG(2940nm) + Nd:YAG(1064nm) 듀얼 파장 레이저 시스템. 색소·재생·리프팅·토닝 복합 시술', '색소, 모공, 흉터, 피부 재생, 토닝', '4파장 레이저로 멜라닌·수분 선택적 흡수. FracTAT 기술, 스무스 모드(진피 가열로 콜라겐 리모델링)', '스타워커(피코토닝), SP Dynamis(리프팅·재생) 등 다양한 플랫폼. 전 세계 80개국 판매', '["포토나 스타워커", "포토나 스타워커 토닝", "포토나 프락셀"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (76, '레블라이트', '레이저(색소/토닝)', 'Q스위치 Nd:YAG(1064nm/532nm) 레이저. PTP 기술로 레이저 토닝에 특화', '기미, 색소, 잡티, 피부 톤', 'Q-switched Nd:YAG 1064nm/532nm. PTP(Photoacoustic Therapy Pulse)로 고출력 에너지를 2회로 나눠 부드럽게 전달', 'RevLite SI가 최신 모델. 최대 1600mJ 출력, 2~8mm 스팟사이즈. Collimate beam 방식', '["레블라이트토닝si", "레블라이트 토닝"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (77, '인트라셀', 'RF 마이크로니들', 'RF 마이크로니들 장비. MTS 효과와 고주파(RF)를 결합하여 진피층 직접 자극', '모공, 흉터, 탄력, 주름', '마이크로니들로 진피층 진입 + RF 에너지 전달 → 콜라겐 리모델링', 'INTRAcel PRO가 최신 모델. 포텐자와 같은 제조사(제이시스). 니들 깊이 조절 가능', '["인트라셀 프로"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 5);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (78, '텐쎄라', '리프팅', '2라인 HIFU(고밀도 집속 초음파) 방식의 리프팅 장비. 시술 시간이 짧고 회복이 빠름', '얼굴 처짐, 턱선, 탄력', 'HIFU 에너지로 진피~SMAS층 열응고 → 콜라겐 리모델링. 2라인 초음파 조사 방식', '텐텍 자체 개발. 식약처 HIFU 허가', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (79, '엑실리스', '바디(RF)', '고주파(RF)로 지방 감소와 피부 타이트닝을 동시에 수행하는 바디/페이스 장비', '체지방 감소, 피부 처짐, 주름', '최대 120W 고출력 RF를 피하 지방층에 전달 → 지방 세포 자연사 유도 + 콜라겐 수축', 'BTL 엑실리스 엘리트. 식약처 BMI 25~35 비만 지방감소 인증. 얼굴/바디 겸용', '["엑실리스 엘리트"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 6);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (80, 'PDRN', '주사 시술(재생)', '폴리디옥시리보뉴클레오타이드(PDRN) 성분의 피부 재생 주사. 연어 DNA 유래', '피부 재생, 탄력, 잔주름, 홍조 진정', 'PDRN이 아데노신 A2A 수용체 활성화 → 섬유아세포 증식 촉진 + 혈관 신생 + 항염', '리쥬란(PN)과 유사하나 분자량 차이. PN은 폴리뉴클레오타이드, PDRN은 더 짧은 DNA 조각', '["연어주사", "피디알엔"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (81, '콜라움', '콜라겐 촉진제', 'PLLA 미세구형 입자 기반 바이오스티뮬레이터. 자가 콜라겐 생성을 촉진', '볼 꺼짐, 주름, 피부 탄력', 'PLLA 미세입자가 진피층에서 콜라겐·엘라스틴·히알루론산 생성 촉진', '콜라움 120(스킨부스터), 콜라움 240(볼륨부스터) 라인업. 스컬트라/올리디아와 동일 PLLA 계열', '["콜라움 120", "콜라움 240"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (82, '쥬브아셀', '스킨부스터', 'hADM(무세포동종진피) 기반 ECM 스킨부스터. 인체 진피 유래 콜라겐·엘라스틴·HA 직접 보충', '피부 탄력, 재생, 잔주름, 피부결', 'hADM에서 세포 제거 후 ECM(콜라겐, 엘라스틴, HA) 성분만 추출 → 진피에 직접 이식', '쥬브아셀 3%(피부결), 8%(집중 재생) 농도별 라인업. 리투오와 유사한 ECM 부스터 계열', '["쥬브아셀 3%", "쥬브아셀3%", "쥬브아셀8%"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (83, '피코하이', '레이저(색소)', '피코세컨드 Nd:YAG 레이저. 원텍 피코케어 시리즈의 고출력 모델', '기미, 색소, 문신, 모공, 흉터', '피코초 펄스로 색소 입자 미세 파쇄. 1064nm/532nm 파장', '원텍 피코케어 시리즈(피코케어 마제스티, 피코케어 450 등). MLA 프락셀 핸드피스 가능', '["피코하이 MLA", "피코케어", "피코케어 마제스티"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 5);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (84, '피코K', '레이저(색소)', '피코세컨드 Nd:YAG 레이저. 루트로닉 피코 시리즈 엔트리 모델', '색소, 토닝', '피코초 1064nm/532nm 펄스', '피코플러스의 엔트리 모델', '["피코레이저k", "피코케이"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (85, '피콜로', '레이저(색소)', '피코세컨드 레이저. 루트로닉 포터블 피코 모델', '색소, 문신 제거', '피코초 Nd:YAG 레이저', '피코플러스/피코하이 대비 소형 포터블 모델', '["피코레이져 -피콜로", "피코프락셀- 피콜로"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (86, '하이드라페이셜', '관리기기(필링)', '물과 석션을 이용해 각질·피지를 제거하고 보습 성분을 동시에 주입하는 아쿠아 필링 장비', '모공, 피지, 각질, 보습, 피부결', 'Vortex-Fusion 기술로 3단계(클렌징→추출→수분공급) 자동 진행. 석션으로 피지·각질 제거 + 세럼 주입', '전 세계 90개국 도입. 30분 시술, 다운타임 없음', '[]', 0, 0, '2026-04-06 08:58:51', '2026-05-19 10:41:03', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (87, '3DEEP', '리프팅(RF)', '3DEEP 기술의 다중 전극 RF 장비. 피부 깊은 곳까지 균일한 열에너지 전달', '피부 탄력, 처짐, 주름', '3DEEP 다중 전극 RF 기술로 진피 깊은 곳까지 균일한 열 전달 → 콜라겐 리모델링', '3DEEP PRO는 프리미엄 모델. 얼굴/바디 겸용', '["3DEEP PRO", "3Deep", "쓰리딥", "3DEEP PRO(바디)"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (88, '루비레이저', '레이저(색소)', '694nm 루비 레이저. 멜라닌 흡수율이 높아 색소 병변 치료에 특화', '오타모반, 깊은 색소, 문신 제거', '694nm 파장이 멜라닌에 선택적 흡수 → 색소 파괴', '깊은 진피 색소(오타모반 등)에 효과적. 글로빔 루비레이저 등', '["루비 레이저", "글로빔 루비레이저"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (89, '백옥주사', '주사 시술', '글루타치온 정맥 주사. 항산화·미백·피로 회복 효과', '피부 미백, 피로 회복, 항산화', '글루타치온(항산화 물질)이 멜라닌 합성 억제 + 활성산소 제거', '신데렐라주사(항산화+비타민), 태반주사(성장인자) 등 유사 주사 시술 다수', '["신데렐라주사", "태반주사", "활력주사", "수액"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (90, '밀크필', '필링', '락틱산(젖산) 기반 화학 필링. 각질 제거 + 보습 효과로 민감한 피부에도 적합', '피부결, 잡티, 모공, 각질', '락틱산이 각질층 사이 결합 약화 → 부드러운 각질 제거 + 보습', '블랙필(살리실산), 핑크필(복합산), 호박필(만델산) 등 필링 종류 다양', '["블랙필", "핑크필", "호박필", "라라필", "샤인필", "부스터필"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (91, '스크러버', '관리기기', '초음파 진동을 이용한 각질·피지 제거 장비', '각질, 피지, 모공', '초음파 진동으로 모공 속 피지·각질을 물리적으로 제거', '관리 시술 기본 3종(이온자임, 소노, 스크러버) 중 하나', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (92, '비타민', '관리기기/시술', '비타민C 등 항산화 성분을 이온토포레시스로 피부에 침투시키는 관리 시술', '미백, 항산화, 피부 톤', '비타민C(아스코르빈산)의 항산화 작용 + 멜라닌 합성 억제', '비타민 관리, 비타민D 등 다양한 구성. 단독 또는 크라이오와 병행', '["비타민관리", "비타민D", "비타민+크라이오", "비타란", "비타"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (93, 'LED', '관리기기(광선)', 'LED(발광다이오드) 광선을 이용한 피부 재생·진정 장비. 파장별 다른 효과', '피부 재생, 진정, 여드름, 콜라겐 촉진', '빨강(633nm): 콜라겐 촉진, 파랑(415nm): 여드름균 살균, 근적외선(830nm): 깊은 재생', '재생 LED, 재생레이저 등으로 불림. 다운타임 없는 보조 시술', '["LED 재생레이저", "재생 LED", "재생LED", "재생레이저", "재생라이트"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (94, '더마샤인', '시술기기(주입)', '자동 미세주입기(메소건). HA·보톡스 등을 균일하게 진피에 주입하는 장비', '물광 시술, 스킨부스터 주입', '다중 니들(9핀)로 일정 깊이·용량의 약물을 자동 주입', '물광주사 시술에 가장 많이 사용되는 자동 주입기. 더마샤인 프로는 업그레이드 모델', '["더마샤인프로"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
