INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (97, '윤곽주사', '주사 시술', '지방 분해 성분(PPC/DC 등)을 주입하여 얼굴/바디 지방을 줄이는 주사 시술', '이중턱, 볼살, 턱선, 바디 지방', '포스파티딜콜린(PPC) + 디옥시콜산(DC) 등이 지방 세포막 파괴 → 지방 분해·배출', '얼굴라인주사, 바디라인주사와 동일 계열', '["얼굴라인주사", "바디라인주사"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (98, '코어스컬프', '바디(EMS/RF)', '전자기장(EMS)으로 근육을 수축시켜 근육량 증가와 지방 감소를 유도하는 바디 장비', '복부, 허벅지, 팔뚝 근육 강화 + 지방 감소', '고강도 전자기장이 근육 초극대 수축 유도 → 근육 성장 + 지방 대사 촉진', '엠스컬프(BTL)와 유사 원리', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 6);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (99, '카복시', '주사 시술', '이산화탄소(CO2) 가스를 피하에 주입하여 혈액순환을 촉진하고 지방 분해를 돕는 시술', '다크서클, 튼살, 셀룰라이트, 지방', 'CO2 가스 주입 → 보어 효과로 산소 공급 증가 → 혈류 개선 + 지방 세포 대사 촉진', '카르복시테라피(Carboxytherapy). 눈밑 다크서클에 다수 사용', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 6);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (100, '엑셀브이', '레이저(혈관/색소)', '532nm(KTP) + 1064nm(Nd:YAG) 듀얼 파장 레이저. 혈관 병변과 색소 치료에 특화', '홍조, 혈관, 색소, 피부 톤', '532nm(혈관) + 1064nm(색소) 듀얼 파장으로 혈관·색소 동시 치료', '큐테라 엑셀브이+가 최신 모델. 셀렉V(IPL)와 같은 제조사', '["엑셀브이+", "셀렉브이"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 2);
