INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (102, '필로가', '스킨부스터', '히알루론산(HA) + 다중 비타민·미네랄 복합 메조치료제. 피부 재생·보습·영양 공급', '피부 보습, 탄력, 잔주름, 피부결', 'HA + 54종 활성 성분(비타민, 미네랄, 아미노산, 코엔자임)을 진피에 주입', '필로가 135(NCTF 135HA)가 대표 제품. 필로르가로도 표기', '["필로가 135", "필로르가 135"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
