INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (120, '오로라레이저', '레이저(색소/혈관)', 'IPL + RF 복합 기술(ELOS)을 이용한 색소·혈관·피부 톤 치료', '색소, 홍조, 혈관, 피부 톤', 'IPL 광에너지 + RF 고주파를 동시 조사 → 색소·혈관 치료 효과 증대', '시너론 ELOS 기술. aurora 고주파와 동일', '["aurora 고주파"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (121, 'ecm 스킨부스터', '스킨부스터', 'ECM(세포외기질) 성분을 피부에 직접 공급하는 스킨부스터 카테고리 총칭', '피부 재생, 탄력, 피부결', 'hADM 유래 ECM 성분(콜라겐, 엘라스틴, HA)을 진피에 주입', '리투오, 쥬브아셀 등이 대표 ECM 부스터. 기존 PN/PDRN과 다른 세대', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'injection', 3);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (122, '바디슈링크', '바디(HIFU)', '슈링크의 바디 전용 카트리지를 사용한 HIFU 시술', '바디 지방, 피부 탄력', 'HIFU 에너지로 바디 피하 지방층 열응고', '슈링크 유니버스 바디 카트리지 사용', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 6);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (123, '엠페이스', '바디/리프팅(EMS)', 'HIFES 기술로 얼굴 근육을 강화하고 피부를 리프팅하는 비침습 장비', '얼굴 근육 강화, 리프팅, 주름', 'HIFES(고강도 표면 전자기 자극) + RF로 얼굴 근육 수축 유도 + 피부 타이트닝', 'BTL의 엠스컬프 기술을 얼굴에 적용한 장비. emface가 영문명', '["BLT사의 emface", "emface"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 1);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (124, '인소닉', '관리기기(초음파)', '초음파 기반 약물 침투 촉진 장비', '약물 흡수 촉진, 보습, 재생', '초음파 에너지로 피부 투과성 증가 → 약물 침투 촉진', '인텐스 울트라와 유사 계열', '["인텐스 울트라", "인텐스울트라"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'care', 7);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (125, '울트라펄스 앙코르', '레이저(CO2/재생)', '울트라펄스 CO2 프락셔널 레이저. 흉터·주름·재생에 고출력 사용', '흉터, 주름, 피부 재생', '울트라펄스 CO2(10,600nm) 프락셔널 조사 → 깊은 열손상으로 강력한 재생', '루메니스 제조. 깊은 흉터 치료에 효과적', '["유펄스"]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 5);
INSERT OR REPLACE INTO device_info (id, name, category, summary, target, mechanism, note, aliases, usage_count, is_verified, created_at, updated_at, device_type, primary_category_id) VALUES (126, '셀르디엠', '바디', '엔더몰로지 기술로 셀룰라이트 분해와 바디 라인 정리를 하는 바디 관리 장비', '셀룰라이트, 바디 라인, 부종', '롤러 + 석션으로 피하 조직을 물리적으로 자극 → 지방 대사 촉진 + 림프 순환 개선', '엔더몰로지(Endermologie). 비침습 바디 관리의 대표 장비', '[]', 0, 0, '2026-04-06 08:58:51', '2026-04-06 08:59:31', 'equipment', 3);
